	if !isHexSum(sum) {

package github_test

import (
	"errors"
	"strings"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"

	"github.com/harnaas/harnaas/cmd/harnaas/cli/source"
	"github.com/harnaas/harnaas/cmd/harnaas/cli/source/github"
)

// TestEveryRefFailureIsShapedProblemThenFix asserts the diagnostic contract over
// the whole ref-resolution failure surface at once.
//
// The list is written out rather than derived, for the reason the command
// surface is: a test that asked the package which errors it declares would agree
// with any set. Adding one is therefore two edits, and the second one is where
// somebody confirms the new message names the asset and leaks nothing.
func TestEveryRefFailureIsShapedProblemThenFix(t *testing.T) {
	t.Parallel()

	// The remote is built with a credential in it, which harnaas never does
	// itself — the point is that a diagnostic printing one would be the type's
	// mistake and not the caller's.
	const remote = "REDACTED"

	failures := map[string]error{
		"unknown ref": &github.UnknownRefError{AssetID: "review", Repository: "acme/assets", Ref: "v9.9.9"},
		"lookup refused": &github.RefLookupError{
			AssetID:    "review",
			Repository: "acme/assets",
			Ref:        "v1.2.0",
			Remote:     remote,
			Err:        errors.New("fatal: repository not found"),
		},
		"git unavailable": &github.GitUnavailableError{Err: errors.New(`exec: "git": executable file not found in $PATH`)},
		// The cause is a real transport diagnostic rather than a plain error,
		// because the credential is redacted by the type that holds the URL —
		// so what this case proves is that quoting a cause's problem carries
		// that redaction with it rather than reaching around it.
		"archive retrieval": &github.ArchiveRetrievalError{
			AssetID:    "review",
			Repository: "acme/assets",
			Commit:     "9f2a1c4e8b7d6a5f4e3c2b1a0987654321fedcba",
			Err:        &source.FetchError{URL: remote, Err: errors.New("no such host")},
		},
		"access denied": &github.AuthorizationError{
			AssetID:     "review",
			Repository:  "acme/assets",
			Commit:      "9f2a1c4e8b7d6a5f4e3c2b1a0987654321fedcba",
			TokenOrigin: "HARNAAS_GITHUB_TOKEN",
			Err:         &source.StatusError{URL: remote, StatusCode: 403, Status: "403 Forbidden"},
		},
		"access denied with no token": &github.AuthorizationError{
			AssetID:    "review",
			Repository: "acme/assets",
			Commit:     "9f2a1c4e8b7d6a5f4e3c2b1a0987654321fedcba",
			Err:        &source.StatusError{URL: remote, StatusCode: 404, Status: "404 Not Found"},
		},
	}

	for name, err := range failures {
		t.Run(name, func(t *testing.T) {
			t.Parallel()

			message := err.Error()

			problem, fix, split := strings.Cut(message, "\n\n")
			require.True(t, split, "the problem and the fix must be separated by a blank line: %s", message)
			assert.NotContains(t, problem, "\n", "the problem is one line")
			assert.NotEmpty(t, fix)

			assert.NotContains(t, message, "hunter2", "no credential reaches a message")
			assert.NotContains(t, message, "token=", "no signed query reaches a message")
		})
	}
}

// TestAManifestFailureNamesTheAssetAndTheRepository holds the two diagnostics
// an author can act on to naming both — a `sources` entry is referenced by any
// number of assets, so the repository alone does not say which line to edit.
func TestAManifestFailureNamesTheAssetAndTheRepository(t *testing.T) {
	t.Parallel()

	failures := map[string]error{
		"unknown ref": &github.UnknownRefError{AssetID: "review", Repository: "acme/assets", Ref: "v9.9.9"},
		"lookup refused": &github.RefLookupError{
			AssetID:    "review",
			Repository: "acme/assets",
			Ref:        "v1.2.0",
			Remote:     "https://github.com/acme/assets.git",
			Err:        errors.New("fatal: repository not found"),
		},
		"archive retrieval": &github.ArchiveRetrievalError{
			AssetID:    "review",
			Repository: "acme/assets",
			Commit:     "9f2a1c4e8b7d6a5f4e3c2b1a0987654321fedcba",
			Err:        errors.New("the host refused"),
		},
		"access denied": &github.AuthorizationError{
			AssetID:     "review",
			Repository:  "acme/assets",
			Commit:      "9f2a1c4e8b7d6a5f4e3c2b1a0987654321fedcba",
			TokenOrigin: "GH_TOKEN",
			Err:         errors.New("403 Forbidden"),
		},
	}

	for name, err := range failures {
		t.Run(name, func(t *testing.T) {
			t.Parallel()

			message := err.Error()
			assert.Contains(t, message, "review")
			assert.Contains(t, message, "acme/assets")
		})
	}
}

// TestALookupWithNoRefNamesTheDefaultBranch pins the one wording that changes
// with the request rather than with the failure: a source declaring no ref was
// resolving the default branch, and a message quoting an empty ref names
// nothing.
func TestALookupWithNoRefNamesTheDefaultBranch(t *testing.T) {
	t.Parallel()

	err := &github.RefLookupError{
		AssetID:    "review",
		Repository: "acme/assets",
		Remote:     "https://github.com/acme/assets.git",
		Err:        errors.New("fatal: repository not found"),
	}

	assert.Contains(t, err.Error(), "the default branch of acme/assets")
}

// TestAnAuthorizationFailureNamesTheTokenItWasMadeWith holds the two halves of
// the rule apart: a run that had a token is told which variable it came from,
// and a run that had none is told every variable one could be supplied through.
// Naming the wrong one of those sends the reader to check a variable they never
// set, or to set one they already have.
func TestAnAuthorizationFailureNamesTheTokenItWasMadeWith(t *testing.T) {
	t.Parallel()

	withToken := &github.AuthorizationError{
		AssetID:     "review",
		Repository:  "acme/assets",
		Commit:      "9f2a1c4e8b7d6a5f4e3c2b1a0987654321fedcba",
		TokenOrigin: "GH_TOKEN",
		Err:         &source.StatusError{URL: "https://api.github.com/x", StatusCode: 403, Status: "403 Forbidden"},
	}
	assert.Contains(t, withToken.Error(), "with the token in GH_TOKEN")
	assert.NotContains(t, withToken.Error(), "HARNAAS_GITHUB_TOKEN",
		"the chain is what a run with no token is offered; a run that had one is told about the one it had")

	withNone := &github.AuthorizationError{
		AssetID:    "review",
		Repository: "acme/assets",
		Commit:     "9f2a1c4e8b7d6a5f4e3c2b1a0987654321fedcba",
		Err:        &source.StatusError{URL: "https://api.github.com/x", StatusCode: 404, Status: "404 Not Found"},
	}
	message := withNone.Error()
	assert.Contains(t, message, "without a token")
	for _, name := range []string{"HARNAAS_GITHUB_TOKEN", "GH_TOKEN", "GITHUB_TOKEN"} {
		assert.Contains(t, message, name, "every way a token could have been supplied is named")
	}
	// The status is still quoted: "not found" is what the forge said, and a
	// message that only talked about tokens would hide it.
	assert.Contains(t, message, "404 Not Found")
}

// TestAnAuthorizationFailureIsNotAManifestEdit holds the one retrieval failure
// whose fix is a token rather than a line in harnaas.json to saying so.
func TestAnAuthorizationFailureIsNotAManifestEdit(t *testing.T) {
	t.Parallel()

	err := &github.AuthorizationError{
		AssetID:     "review",
		Repository:  "acme/assets",
		Commit:      "9f2a1c4e8b7d6a5f4e3c2b1a0987654321fedcba",
		TokenOrigin: "HARNAAS_GITHUB_TOKEN",
		Err:         errors.New("403 Forbidden"),
	}

	assert.NotContains(t, err.Error(), "harnaas.json")
}

// TestGitUnavailableSendsNobodyToEditTheManifest holds the one diagnostic here
// that is not about the manifest to saying so: nothing an author writes in
// harnaas.json would install git, and a message naming the file would send them
// to edit one that is already correct.
func TestGitUnavailableSendsNobodyToEditTheManifest(t *testing.T) {
	t.Parallel()

	err := &github.GitUnavailableError{Err: errors.New("not found")}

	assert.NotContains(t, err.Error(), "harnaas.json")
	assert.Contains(t, err.Error(), "Install git")
}

package github

import (
	"errors"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"

	"github.com/harnaas/harnaas/cmd/harnaas/cli/source"
)

// The cache seen from the kind that fills it. What the store itself guarantees
// is asserted where it lives; what matters here is the order the three
// memories are consulted in — this run's memo, then this machine's cache, then
// the forge — and that only content the forge actually served is filed.
//
// These tests move HARNAAS_CACHE_DIR, so they do not run in parallel.

// cachedRun resolves one asset through its own kind, which is what a second run
// of harnaas is: a fresh memo over the same cache.
func cachedRun(t *testing.T, cache *source.ArchiveCache, fetcher *countingFetcher) error {
	t.Helper()

	kind := newKind(answeringRunner(tagListing, nil), fetcher.fetch, source.Credential{}, cache)

	_, err := kind.Resolve(t.Context(), resolveRequest("review", "v1.2.0", "skills/review"))
	return err
}

func TestASecondRunResolvesFromTheCacheWithoutFetching(t *testing.T) {
	t.Setenv(source.CacheDirEnvVar, t.TempDir())
	cache := source.NewArchiveCache()

	first := &countingFetcher{body: assetArchive(t)}
	require.NoError(t, cachedRun(t, cache, first))
	require.Len(t, first.asked(), 1)

	second := &countingFetcher{err: errors.New("the network is not available")}
	require.NoError(t, cachedRun(t, cache, second),
		"the archive the first run fetched is still on this machine")
	assert.Empty(t, second.asked(), "a cached archive is not fetched again")
}

// TestABypassedCacheFetchesFresh is the same two runs with the bypass, and is
// what makes the test above an assertion about the cache rather than about the
// memo.
func TestABypassedCacheFetchesFresh(t *testing.T) {
	t.Setenv(source.CacheDirEnvVar, t.TempDir())

	first := &countingFetcher{body: assetArchive(t)}
	require.NoError(t, cachedRun(t, nil, first))

	second := &countingFetcher{body: assetArchive(t)}
	require.NoError(t, cachedRun(t, nil, second))

	assert.Len(t, second.asked(), 1, "a run handed no cache reads nothing an earlier one left")
}

// TestAFailedRetrievalIsNotCached keeps the cross-run memory a memory of
// content: the within-run memo remembers a failure so one outage is not
// multiplied by the assets that met it, and that reasoning expires with the run.
func TestAFailedRetrievalIsNotCached(t *testing.T) {
	t.Setenv(source.CacheDirEnvVar, t.TempDir())
	cache := source.NewArchiveCache()

	refused := &countingFetcher{err: errors.New("the host refused")}
	require.Error(t, cachedRun(t, cache, refused))

	recovered := &countingFetcher{body: assetArchive(t)}
	require.NoError(t, cachedRun(t, cache, recovered),
		"the next run tries again rather than replaying yesterday's outage")
}

package github

import (
	"archive/tar"
	"bytes"
	"compress/gzip"
	"context"
	"errors"
	"maps"
	"slices"
	"strings"
	"sync"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"

	"github.com/harnaas/harnaas/cmd/harnaas/cli/manifest"
	"github.com/harnaas/harnaas/cmd/harnaas/cli/source"
)

const (
	// commitID is the commit every archive in this file is of, and the one the
	// tag below resolves to.
	commitID = "9f2a1c4e8b7d6a5f4e3c2b1a0987654321fedcba"

	// otherCommitID is a second commit in the same repository, which is what
	// makes "at most once per repository *and commit*" testable as more than
	// "at most once per repository".
	otherCommitID = "3d5b7e9012a4c6e8f0b2d4a6c8e02468ace13579"

	// wrapper is the top-level directory a forge puts around a repository
	// archive. Its spelling is the forge's to choose, which is why extraction
	// takes it from the archive rather than reconstructing it.
	wrapper = "acme-assets-9f2a1c4/"
)

// tagListing is what `ls-remote` prints for a repository whose tag v1.2.0 is a
// lightweight tag on commitID.
var tagListing = commitID + "\trefs/tags/v1.2.0\n"

// resolveRequest builds a request for one asset at a path within the source.
func resolveRequest(id, ref, path string) source.Request {
	req := request(ref)
	req.Asset.ID = id
	req.Asset.Ref = manifest.AssetRef{SourceKey: "acme", Path: path}
	return req
}

// archiveOf builds the gzipped tar a forge serves, wrapping every named file in
// the archive's single top-level directory.
func archiveOf(tb testing.TB, files map[string]string) []byte {
	tb.Helper()

	var buffer bytes.Buffer
	gz := gzip.NewWriter(&buffer)
	writer := tar.NewWriter(gz)

	for _, name := range slices.Sorted(maps.Keys(files)) {
		require.NoError(tb, writer.WriteHeader(&tar.Header{
			Name:     wrapper + name,
			Typeflag: tar.TypeReg,
			Size:     int64(len(files[name])),
			Mode:     0o644,
		}))
		_, err := writer.Write([]byte(files[name]))
		require.NoError(tb, err)
	}

	require.NoError(tb, writer.Close())
	require.NoError(tb, gz.Close())
	return buffer.Bytes()
}

// assetArchive is a plausible asset repository: two skills and a rule, so a
// declared subtree has both something to select and something to leave behind.
func assetArchive(tb testing.TB) []byte {
	tb.Helper()

	return archiveOf(tb, map[string]string{
		"README.md":                       "# assets",
		"skills/review/SKILL.md":          "review skill",
		"skills/review/reference/list.md": "checklist",
		"skills/release/SKILL.md":         "release skill",
		"rules/house-style.md":            "house style",
	})
}

// diagnostic is an error shaped the way the transport's own are: a problem, a
// blank line and a fix.
//
// It is a type rather than an errors.New value because revive refuses a message
// ending in punctuation — which is the same reason every diagnostic harnaas
// prints is a type with an Error method rather than a sentinel.
type diagnostic string

// Error renders the diagnostic as written.
func (d diagnostic) Error() string { return string(d) }

// countingFetcher answers every request with body and counts the URLs it was
// asked for, which is how "fetched at most once" is asserted as a number rather
// than inferred from a result that happens to be right.
type countingFetcher struct {
	mu          sync.Mutex
	urls        []string
	credentials []source.Credential
	body        []byte
	err         error
}

// fetch is the [archiveFetcher] the kind is built with.
func (f *countingFetcher) fetch(_ context.Context, url string, credential source.Credential) ([]byte, error) {
	f.mu.Lock()
	defer f.mu.Unlock()

	f.urls = append(f.urls, url)
	f.credentials = append(f.credentials, credential)
	if f.err != nil {
		return nil, f.err
	}
	return f.body, nil
}

// asked returns the URLs the kind fetched, in order.
func (f *countingFetcher) asked() []string {
	f.mu.Lock()
	defer f.mu.Unlock()

	return slices.Clone(f.urls)
}

// presented returns the credentials the kind fetched with, in the same order.
func (f *countingFetcher) presented() []source.Credential {
	f.mu.Lock()
	defer f.mu.Unlock()

	return slices.Clone(f.credentials)
}

func TestAnArchiveURLNamesTheCommitRatherThanTheRef(t *testing.T) {
	t.Parallel()

	got := archiveURL(repository, commitID)

	assert.Equal(t, "https://api.github.com/repos/acme/assets/tarball/"+commitID, got)
	assert.NotContains(t, got, "v1.2.0", "the ref has already been spent; the URL names an object that cannot move")
}

func TestResolveProducesTheSubtreeAndItsProvenance(t *testing.T) {
	t.Parallel()

	fetcher := &countingFetcher{body: assetArchive(t)}
	kind := newKind(answeringRunner(tagListing, nil), fetcher.fetch, source.Credential{}, nil)

	resolved, err := kind.Resolve(t.Context(), resolveRequest("review", "v1.2.0", "skills/review"))
	require.NoError(t, err)

	paths := make([]string, 0, len(resolved.Files))
	for _, file := range resolved.Files {
		paths = append(paths, file.Path)
	}
	assert.Equal(t, []string{"SKILL.md", "reference/list.md"}, paths)

	assert.Equal(t, source.Provenance{
		Kind:           manifest.SourceKindGitHub,
		Source:         "github:acme/assets@v1.2.0",
		RequestedRef:   "v1.2.0",
		ResolvedCommit: commitID,
	}, resolved.Provenance, "the ref asked for is recorded beside the commit it resolved to, never collapsed into it")
	assert.NotEmpty(t, resolved.Digest)
}

func TestABranchResolvesToAMutableSource(t *testing.T) {
	t.Parallel()

	fetcher := &countingFetcher{body: assetArchive(t)}
	kind := newKind(answeringRunner(commitID+"\trefs/heads/main\n", nil), fetcher.fetch, source.Credential{}, nil)

	resolved, err := kind.Resolve(t.Context(), resolveRequest("review", "main", "skills/review"))
	require.NoError(t, err)

	assert.True(t, resolved.Provenance.Mutable, "a branch can name something else tomorrow, and the lockfile has to say so")
}

func TestOneRepositoryAndCommitIsFetchedOncePerRun(t *testing.T) {
	t.Parallel()

	fetcher := &countingFetcher{body: assetArchive(t)}
	kind := newKind(answeringRunner(tagListing, nil), fetcher.fetch, source.Credential{}, nil)

	for _, asset := range []struct{ id, path string }{
		{id: "review", path: "skills/review"},
		{id: "release", path: "skills/release"},
		{id: "house-style", path: "rules/house-style.md"},
	} {
		resolved, err := kind.Resolve(t.Context(), resolveRequest(asset.id, "v1.2.0", asset.path))
		require.NoError(t, err)
		assert.NotEmpty(t, resolved.Files, "every asset is extracted from the one archive")
	}

	assert.Len(t, fetcher.asked(), 1, "three assets in one repository at one commit share a single retrieval")
}

func TestASecondCommitIsItsOwnFetch(t *testing.T) {
	t.Parallel()

	archive := assetArchive(t)
	fetcher := &countingFetcher{body: archive}
	kind := newKind(func(_ context.Context, args ...string) ([]byte, error) {
		// The commit a ref resolves to is what keys the memo, so the two refs
		// here have to answer differently for the test to mean anything.
		if slices.Contains(args, "refs/tags/v1.3.0") {
			return []byte(otherCommitID + "\trefs/tags/v1.3.0\n"), nil
		}
		return []byte(tagListing), nil
	}, fetcher.fetch, source.Credential{}, nil)

	for _, ref := range []string{"v1.2.0", "v1.2.0", "v1.3.0"} {
		_, err := kind.Resolve(t.Context(), resolveRequest("review", ref, "skills/review"))
		require.NoError(t, err)
	}

	assert.Equal(t, []string{
		archiveURL(repository, commitID),
		archiveURL(repository, otherCommitID),
	}, fetcher.asked())
}

func TestConcurrentResolutionsStillFetchOnce(t *testing.T) {
	t.Parallel()

	fetcher := &countingFetcher{body: assetArchive(t)}
	kind := newKind(answeringRunner(tagListing, nil), fetcher.fetch, source.Credential{}, nil)

	var group sync.WaitGroup
	for range 8 {
		group.Add(1)
		go func() {
			defer group.Done()

			_, err := kind.Resolve(t.Context(), resolveRequest("review", "v1.2.0", "skills/review"))
			assert.NoError(t, err)
		}()
	}
	group.Wait()

	assert.Len(t, fetcher.asked(), 1)
}

func TestARetrievalFailureNamesTheAssetTheRepositoryAndTheCommit(t *testing.T) {
	t.Parallel()

	fetcher := &countingFetcher{err: diagnostic("could not fetch https://api.github.com/x: no such host\n\nCheck that this machine can reach the host.")}
	kind := newKind(answeringRunner(tagListing, nil), fetcher.fetch, source.Credential{}, nil)

	resolved, err := kind.Resolve(t.Context(), resolveRequest("review", "v1.2.0", "skills/review"))
	require.Nil(t, resolved, "a failed retrieval never resolves to content, empty or otherwise")

	var retrieval *ArchiveRetrievalError
	require.ErrorAs(t, err, &retrieval)
	assert.Equal(t, "review", retrieval.AssetID)
	assert.Equal(t, repository, retrieval.Repository)
	assert.Equal(t, commitID, retrieval.Commit)
}

func TestARememberedFailureNamesTheAssetThatMetIt(t *testing.T) {
	t.Parallel()

	fetcher := &countingFetcher{err: errors.New("the host refused")}
	kind := newKind(answeringRunner(tagListing, nil), fetcher.fetch, source.Credential{}, nil)

	first, firstErr := kind.Resolve(t.Context(), resolveRequest("review", "v1.2.0", "skills/review"))
	second, secondErr := kind.Resolve(t.Context(), resolveRequest("release", "v1.2.0", "skills/release"))

	require.Nil(t, first)
	require.Nil(t, second)
	assert.Len(t, fetcher.asked(), 1, "a repository that could not be fetched is not asked again for the next asset")
	assert.Contains(t, firstErr.Error(), `"review"`)
	assert.Contains(t, secondErr.Error(), `"release"`, "the remembered failure is attributed to the asset reading it")
}

func TestNoFailurePathResolvesToContent(t *testing.T) {
	t.Parallel()

	archive := assetArchive(t)

	cases := []struct {
		name    string
		listing string
		fetcher *countingFetcher
		path    string
	}{
		{
			name:    "unknown ref",
			fetcher: &countingFetcher{body: archive},
			path:    "skills/review",
		},
		{
			name:    "retrieval refused",
			listing: tagListing,
			fetcher: &countingFetcher{err: errors.New("the host refused")},
			path:    "skills/review",
		},
		{
			name:    "archive is not an archive",
			listing: tagListing,
			fetcher: &countingFetcher{body: []byte("<!doctype html>")},
			path:    "skills/review",
		},
		{
			name:    "path is not at the commit",
			listing: tagListing,
			fetcher: &countingFetcher{body: archive},
			path:    "skills/missing",
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()

			kind := newKind(answeringRunner(tc.listing, nil), tc.fetcher.fetch, source.Credential{}, nil)

			resolved, err := kind.Resolve(t.Context(), resolveRequest("review", "v1.2.0", tc.path))
			require.Error(t, err)
			assert.Nil(t, resolved, "no failure hands on a source, so none can converge to deleting what the asset installed")
			assert.Contains(t, err.Error(), "review", "every failure names the asset the author would go and edit")
		})
	}
}

func TestARetrievalFailureQuotesTheCausesProblemAndNotItsFix(t *testing.T) {
	t.Parallel()

	cause := diagnostic("example.invalid answered 404 Not Found\n\nCheck that the source the manifest declares exists.")
	err := &ArchiveRetrievalError{AssetID: "review", Repository: repository, Commit: commitID, Err: cause}

	message := err.Error()
	assert.Contains(t, message, "answered 404 Not Found")
	assert.NotContains(t, message, "Check that the source the manifest declares exists.",
		"one message offers one fix, or the reader has to decide which of two is theirs")
	assert.Equal(t, 1, strings.Count(message, "\n\n"), "problem, blank line, fix")
	require.ErrorIs(t, err, cause)
}

// Package github resolves `github` sources: the ref a manifest pinned becomes
// the commit it names, and that commit's repository archive becomes the files
// an asset installs.
//
// Names are resolved with Git and bytes are moved over HTTPS, and the split is
// the whole design. `git ls-remote` goes through whatever credential helper the
// user already configured, so a private repository resolves without harnaas
// inventing an authentication story of its own, and that path has no API rate
// limit for a CI job to exhaust. The archive endpoint is then one request per
// repository and commit rather than one request per file, which is what makes a
// skill — a directory of documents — cost the same as a rule.
//
// Resolution is kept separate from retrieval for a second reason: the lockfile
// records what was *asked for* alongside what it *resolved to*, because "the
// installed files still match the commit" and "the tag now points somewhere
// else" are two different questions and `lint` asks them separately.
package github

// remoteHost is the forge this kind speaks to, and the only place its name is
// spelled: a message, a Git remote and an archive URL all read it from here, so
// they cannot come to disagree about which host a `github` source means.
const remoteHost = "github.com"

// remoteURL is the Git remote for an `owner/repository` pair.
//
// It is built rather than taken from the manifest, which is what keeps a
// declared source from naming a host harnaas never agreed to talk to. The
// repository arrives already checked for shape by the manifest grammar, so this
// is assembly and not validation.
func remoteURL(repository string) string {
	return "https://" + remoteHost + "/" + repository + ".git"
}

